  id: string;
  name: string;
  children?: Category[];
}

const rootCategories: Category[] = [
  {
    id: 'category1',
    name: 'Category 1'
  },
  {
    id: 'category2',
    name: 'Category 2',
    children: [
      {
        id: 'subcategory1a',
        name: 'Subcategory 1A'
      },
      {
        id: 'subcategory1b',
        name: 'Subcategory 1B'
      }
    ]
  },
  // Add more categories here...
];
```

### Step 4: Create TreeGrid Component

Create a component that will render the treegrid:

```typescript
// src/app/tree-grid.component.ts
import { Component } from '@angular/core';
import { MatTreeGridComponent } from '@swimlane/ngx-treegrid';

@Component({
  selector: 'app-tree-grid',
  template: `
    <mat-tree-grid #treeGrid>
      <mat-tree-node *ngFor="let category of categories" [item]="category">
        {{ category.name }}
        <mat-tree-node *ngIf="category.children?.length > 0" [ref]="childNodeRef"></mat-tree-node>
      </mat-tree-node>
    </mat-tree-grid>
  `,
})
export class TreeGridComponent implements OnInit {
  categories: Category[];

  constructor(private treeGrid: MatTreeGridComponent<{}, Category>) {}

  ngOnInit(): void {
    this.treeGrid.categories = rootCategories;
  }

  get childNodeRef() {
    return this.treeGrid.ref.find((node): node is MatTreeNode => !!node);
  }
}
```

